import{_ as l,C as o,o as n,c as i,j as e,a as r,E as s,ap as g}from"./chunks/framework.Cts_cdse.js";const h="/Diana-Cl/ai/ai-2.png",_=JSON.parse('{"title":"لیست ابزارهای هوش مصنوعی","description":"جعبه‌ابزار شخصی من؛ از مدل‌های زبانی تا دستیارهای برنامه‌نویسی","frontmatter":{"layout":"doc","outline":"deep","lang":"fa-IR","dir":"rtl","title":"لیست ابزارهای هوش مصنوعی","description":"جعبه‌ابزار شخصی من؛ از مدل‌های زبانی تا دستیارهای برنامه‌نویسی","date":"2025-11-21T00:00:00.000Z","editLink":true,"head":[["meta",{"name":"keywords","content":"Gemini 3 pro, Google studio, ChatGPT 5.1, Claude Sonnet 4.5, DeepSeek, Kimi 2, Arena, Mistral, Grok4.1, Qween 3, Baidu"}]]},"headers":[],"relativePath":"topics/ai-daily.md","filePath":"topics/ai-daily.md"}'),d={name:"topics/ai-daily.md"},p={id:"‏-ai-های-اصلی-و-روزمره",tabindex:"-1"};function f(u,t,c,m,b,k){const a=o("Badge");return n(),i("div",null,[t[3]||(t[3]=e("h1",{id:"جعبه‌ابزار-هوش-مصنوعی-من-✨",tabindex:"-1"},[r("جعبه‌ابزار هوش مصنوعی من ✨ "),e("a",{class:"header-anchor",href:"#جعبه‌ابزار-هوش-مصنوعی-من-✨","aria-label":'Permalink to "جعبه‌ابزار هوش مصنوعی من ✨"'},"​")],-1)),t[4]||(t[4]=e("p",null,"در این صفحه، لیست مدل‌ها و ابزارهایی که شخصاً به صورت روتین استفاده می‌کنم را معرفی کرده‌ام. انتخاب‌های من بر اساس سرعت، دقت و کاربرد در برنامه‌نویسی و تحقیقات دسته‌بندی شده‌اند.",-1)),t[5]||(t[5]=e("br",null,null,-1)),t[6]||(t[6]=e("p",{align:"center"},[e("img",{src:h,alt:"Ai",width:"2752px"})],-1)),e("h2",p,[t[0]||(t[0]=r("‏ AI های اصلی و روزمره ",-1)),s(a,{type:"info",text:"🌟"}),t[1]||(t[1]=r()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#‏-ai-های-اصلی-و-روزمره","aria-label":'Permalink to "‏ AI های اصلی و روزمره <Badge type="info" text="🌟" />"'},"​",-1))]),t[7]||(t[7]=g('<div class="info custom-block"><p class="custom-block-title">انتخاب‌های اول و آخر من (Daily Drivers)</p><p>من برای استفاده‌ی روتین، این اپلیکیشن‌ها را همیشه نصب دارم: <strong>Gemini</strong>, <strong>GPT</strong>, <strong>Claude</strong>, <strong>Grok</strong> و <strong>Perplexity</strong>.</p></div><h2 id="🏆-مدل‌های-زبانی-اصلی-llms" tabindex="-1">🏆 مدل‌های زبانی اصلی (LLMs) <a class="header-anchor" href="#🏆-مدل‌های-زبانی-اصلی-llms" aria-label="Permalink to &quot;🏆 مدل‌های زبانی اصلی (LLMs)&quot;">​</a></h2><h3 id="‏-gemini-جمنای" tabindex="-1">‏ Gemini (جمنای) <a class="header-anchor" href="#‏-gemini-جمنای" aria-label="Permalink to &quot;‏ Gemini (جمنای)&quot;">​</a></h3><p>انتخاب اول من. چه از طریق اپلیکیشن و چه از طریق <a href="https://aistudio.google.com/prompt" target="_blank" rel="noreferrer">Google AI Studio</a>.</p><ul><li><strong>مدل پیشنهادی:</strong> Gemini 1.5 Pro (نسخه ۳ هنوز به طور عمومی تایید نشده اما مدل‌های جدید گوگل دائما رکورد می‌زنند).</li><li><strong>کاربرد:</strong> تحلیل‌های سنگین، ورودی‌های طولانی.</li><li><strong>نکته:</strong> دیگه اون گیجِ قدیم نیست! تمام رکوردها رو جابجا کرده.</li></ul><h3 id="claude-کلاد" tabindex="-1">Claude (کلاد) <a class="header-anchor" href="#claude-کلاد" aria-label="Permalink to &quot;Claude (کلاد)&quot;">​</a></h3><p>وقتی صحبت از <strong>کدنویسی</strong> باشه، می‌پیچم میرم سراغ Claude.</p><ul><li><strong>مدل:</strong> Sonnet 4.5</li><li><strong>مزیت:</strong> فوق حرفه‌ای برای کد، رنک یک دنیا.</li><li><strong>روش دسترسی:</strong> اپ رسمی، یا از طریق <a href="https://lmarena.ai/" target="_blank" rel="noreferrer">Arena</a> و <a href="https://poe.com" target="_blank" rel="noreferrer">Poe</a>.</li><li><strong>نکته:</strong> وریفای شماره غیر ایران می‌خواد (با شماره مجازی حل میشه) اما پلن رایگانش محدودیت داره.</li></ul><h3 id="grok-گراک" tabindex="-1">Grok (گراک) <a class="header-anchor" href="#grok-گراک" aria-label="Permalink to &quot;Grok (گراک)&quot;">​</a></h3><ul><li><strong>نسخه:</strong> Grok-4.1</li><li><strong>مزیت:</strong> سریع‌ترین LLM دنیا، متعلق به کمپانی X.AI و <strong>بدون سانسور واقعی</strong>.</li><li><strong>مدل تخصصی:</strong> Grok Code Fast برای برنامه‌نویسی.</li></ul><h3 id="chatgpt" tabindex="-1">ChatGPT <a class="header-anchor" href="#chatgpt" aria-label="Permalink to &quot;ChatGPT&quot;">​</a></h3><ul><li><strong>توضیح:</strong> نیاز به تعریف داره مگه؟</li><li><strong>کاربرد:</strong> نگاه تحلیلی، جستجوی عمیق (با مدل‌هایی مثل 5.1 یا o3 یا 4o).</li></ul><hr><br><h2 id="🇨🇳-غول‌های-چینی-شگفت‌انگیز-و-رایگان" tabindex="-1">🇨🇳 غول‌های چینی (شگفت‌انگیز و رایگان) <a class="header-anchor" href="#🇨🇳-غول‌های-چینی-شگفت‌انگیز-و-رایگان" aria-label="Permalink to &quot;🇨🇳 غول‌های چینی (شگفت‌انگیز و رایگان)&quot;">​</a></h2><p>این مدل‌ها دارن بازار رو میگیرن و برای استفاده‌های عمومی عالی هستن:</p><table tabindex="0"><thead><tr><th style="text-align:left;">نام مدل</th><th style="text-align:left;">ویژگی بارز</th><th style="text-align:left;">لینک/توضیحات</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>DeepSeek</strong></td><td style="text-align:left;">ساده، بی‌دردسر، رایگان</td><td style="text-align:left;">عالی برای نصب روی گوشی پدر و مادرها.</td></tr><tr><td style="text-align:left;"><strong>Qwen (AliBaba)</strong></td><td style="text-align:left;">ایجنت کمپانی علی‌بابا</td><td style="text-align:left;">خیلی حرف‌ها برای گفتن داره.</td></tr><tr><td style="text-align:left;"><strong>Kimi (Moonshot)</strong></td><td style="text-align:left;">مدل K2</td><td style="text-align:left;">قابلیت آپلود ۵۰ فایل همزمان! ثبت نام با جیمیل.</td></tr><tr><td style="text-align:left;"><strong>Chat.Z.AI</strong></td><td style="text-align:left;">مدل GLM-4</td><td style="text-align:left;">رسماً داره غوغا می‌کنه.</td></tr><tr><td style="text-align:left;"><strong>Ernie (Baidu)</strong></td><td style="text-align:left;">چینی جدیدالورود</td><td style="text-align:left;">حسابی ترکونده.</td></tr></tbody></table><hr><br><h2 id="💻-دستیارهای-برنامه‌نویسی-و-توسعه" tabindex="-1">💻 دستیارهای برنامه‌نویسی و توسعه <a class="header-anchor" href="#💻-دستیارهای-برنامه‌نویسی-و-توسعه" aria-label="Permalink to &quot;💻 دستیارهای برنامه‌نویسی و توسعه&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">پیشنهاد ویژه</p><p>اگر درخواست برنامه‌نویسی دارید و حوصله کپی پیست ندارید، <strong>Cursor</strong> بهترین گزینه است.</p></div><ul><li><strong><a href="https://www.cursor.com/" target="_blank" rel="noreferrer">Cursor AI</a>:</strong> بدون هیچ دانشی کد بزن! ادیتور محبوب این روزها.</li><li><strong><a href="https://jules.google/" target="_blank" rel="noreferrer">Jules (Google)</a>:</strong> سوپر ایجنت گوگل. رپوی گیت‌هاب رو کلون می‌کنه، تغییر میده، تست می‌کنه و کامیت می‌کنه. محشره.</li><li><strong><a href="https://mistral.ai/" target="_blank" rel="noreferrer">Mistral</a>:</strong> هوش مصنوعی قدرتمند و اپن‌سورس اروپا.</li><li><strong><a href="https://dev.ai/" target="_blank" rel="noreferrer">Dev AI</a>:</strong> مناسب برای دستیار برنامه‌نویسی سطح مبتدی.</li><li><strong><a href="https://useadrenaline.com/" target="_blank" rel="noreferrer">Adrenaline</a>:</strong> دستیار تخصصی برای دیباگ و درک کد.</li><li><strong>Diana-Cl List:</strong> <a href="https://diana-cl.github.io/Diana-Cl/en/topics/ai" target="_blank" rel="noreferrer">فهرستی برگزیده از ابزارهای برنامه‌نویسی</a>.</li></ul><hr><br><h2 id="🔍-جستجو-و-تحقیقات-search-research" tabindex="-1">🔍 جستجو و تحقیقات (Search &amp; Research) <a class="header-anchor" href="#🔍-جستجو-و-تحقیقات-search-research" aria-label="Permalink to &quot;🔍 جستجو و تحقیقات (Search &amp; Research)&quot;">​</a></h2><p>وقتی دنبال فکت‌های دقیق هستید نه فقط تولید متن:</p><ol><li><strong><a href="https://www.perplexity.ai/" target="_blank" rel="noreferrer">Perplexity</a>:</strong> قطعا بهترینِ حوزه‌ خودشه. موتور جستجوی آینده.</li><li><strong><a href="https://notebooklm.google/" target="_blank" rel="noreferrer">NotebookLM</a>:</strong> مدل جدید گوگل که دنیای تحقیقات رو متحول می‌کنه (تبدیل جزوه به پادکست و...).</li><li><strong><a href="https://genspark.ai/" target="_blank" rel="noreferrer">Genspark</a>:</strong> سوپر ایجنت و پارتنر OpenAI.</li><li><strong><a href="https://medisearch.io/" target="_blank" rel="noreferrer">MediSearch</a>:</strong> متخصص سوالات حوزه پزشکی و دارویی.</li><li><strong><a href="https://vidclue.com/" target="_blank" rel="noreferrer">VidClue</a>:</strong> جستجو در ویدئو! مثل سرچ در متن.</li></ol><hr><br><h2 id="🎨-مالتی‌مدیا-و-ابزارهای-خلاقانه" tabindex="-1">🎨 مالتی‌مدیا و ابزارهای خلاقانه <a class="header-anchor" href="#🎨-مالتی‌مدیا-و-ابزارهای-خلاقانه" aria-label="Permalink to &quot;🎨 مالتی‌مدیا و ابزارهای خلاقانه&quot;">​</a></h2><ul><li><strong>طراحی UI:</strong> ابزار <a href="https://v0.dev/" target="_blank" rel="noreferrer">v0.dev</a> (یکپارچه با Figma و React).</li><li><strong>پاورپوینت:</strong> اگر هنوز دستی پاورپوینت می‌سازی، <a href="https://gamma.app/" target="_blank" rel="noreferrer">این ابزارها</a> رو چک کن.</li><li><strong>ویدئو به متن:</strong> ابزار <a href="https://chatwith.tools/youtube-summarizer" target="_blank" rel="noreferrer">YouTube Summarizer</a> و <a href="http://useremy.com/" target="_blank" rel="noreferrer">Remy</a> (ویدئو رو دیده و جواب میده).</li><li><strong>PDF:</strong> <a href="https://www.getcoralai.com/" target="_blank" rel="noreferrer">Coral AI</a> متخصص فایل‌های PDF.</li><li><strong>ریاضی:</strong> <a href="https://mathgpt.pro/" target="_blank" rel="noreferrer">MathGPT</a> برای حل مسائل پیچیده.</li></ul><hr><br><h2 id="🌐-پلتفرم‌های-تجمیعی-all-in-one" tabindex="-1">🌐 پلتفرم‌های تجمیعی (All-in-One) <a class="header-anchor" href="#🌐-پلتفرم‌های-تجمیعی-all-in-one" aria-label="Permalink to &quot;🌐 پلتفرم‌های تجمیعی (All-in-One)&quot;">​</a></h2><p>جایی که می‌تونید به چندین مدل همزمان دسترسی داشته باشید:</p><ul><li><strong><a href="https://chat.lmsys.org/" target="_blank" rel="noreferrer">LMSYS Arena</a>:</strong> سوال بپرس، دو مدل رندوم جواب میدن، انتخاب کن کدوم بهتره (رایگان).</li><li><strong><a href="https://poe.com/" target="_blank" rel="noreferrer">Poe</a>:</strong> دسترسی به اکثر مدل‌ها.</li><li><strong><a href="https://huggingface.co/models" target="_blank" rel="noreferrer">HuggingFace</a>:</strong> خانه مدل‌های اوپن‌سورس.</li><li><strong><a href="https://you.com/" target="_blank" rel="noreferrer">You.com</a>:</strong> رابط کاربری یکپارچه.</li><li><strong><a href="http://app.chatbetter.com/" target="_blank" rel="noreferrer">ChatBetter</a>:</strong> رابط کاربری برای GPT, Claude, Kimi, Llama.</li></ul><div class="warning custom-block"><p class="custom-block-title">نظر عمومی</p><p>بیخود‌ترین AI دنیا فعلا متعلق به کمپانی متا (Meta) هست (البته Llama اوپن‌سورسه و خوبه، ولی چت‌باتش هم ترکیده هم اصلا هرکاری کنی به ایران سرویس نمی‌ده خودتو خسته نکن).</p></div>',37))])}const y=l(d,[["render",f]]);export{_ as __pageData,y as default};
